 "info": [
  {
   "field": "identity_details",
   "about": "Any 2 of date of birth, email, phone number and address, checked against the records (only if not already verified in this conversation)",
   "from": "customer",
   "ask": "To verify your identity, could you please give me two of these: your date of birth, email, phone number or address on file?",
   "may_hold_back": false
  },
  {
   "field": "account_to_close",
   "about": "The checking account the customer wants to close (account_id, class, balance, date_opened, status)",
   "from": "records",
   "ask": "Which checking account would you like to close?",
   "may_hold_back": false
  },
  {
   "field": "funding_method_for_fee",
   "about": "How the customer will put the early closure fee into the account if the balance is below the fee: depositing a check themselves, or an internal transfer from another of their accounts",
   "from": "customer",
   "ask": "The early closure fee has to be paid from the account balance. How would you like to add funds to cover it?",
   "may_hold_back": true
  },
  {
   "field": "fee_transfer_source",
   "about": "Which of the customer's other OPEN accounts to transfer the fee amount from, and their authorization",
   "from": "customer",
   "ask": "Which of your accounts should I transfer the fee amount from, and do you authorize that transfer?",
   "may_hold_back": true
  },
  {
   "field": "remaining_balance_destination",
   "about": "Which of the customer's open accounts should receive the balance left above the requirement before closure",
   "from": "customer",
   "ask": "Your account still has a balance. Which of your accounts should I move it to before closing?",
   "may_hold_back": false
  },
  {
   "field": "split_amounts",
   "about": "If the customer wants the balance split across several of their accounts: each destination and the amount for it",
   "from": "customer",
   "ask": "How much should go to each account?",
   "may_hold_back": true
  },
  {
   "field": "terms_accepted",
   "about": "Whether the customer accepts the early closure fee (if any) and the notice period",
   "from": "customer",
   "ask": "Would you like to proceed with the closure on these terms?",
   "may_hold_back": false
  }
 ],
 "steps": [
